@Service
public class JwtService {

    private final SecretKey key;
    private final Duration accessTtl;
    private final Duration refreshTtl;

    public JwtService(@Value("${learn-hub.jwt-secret}") String secret,
                      @Value("${learn-hub.jwt.access-ttl:PT30M}") Duration accessTtl,
                      @Value("${learn-hub.jwt.refresh-ttl:P7D}") Duration refreshTtl) {
        this.key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.accessTtl = accessTtl;
        this.refreshTtl = refreshTtl;
    }

    public String issue(Long userId, String type) {
        Duration ttl = "refresh".equals(type) ? refreshTtl : accessTtl;
        Instant now = Instant.now();
        return Jwts.builder()
                .subject(String.valueOf(userId))
                .claim("typ", type)
                .id(UUID.randomUUID().toString())
                .issuedAt(Date.from(now))
                .expiration(Date.from(now.plus(ttl)))
                .signWith(key, Jwts.SIG.HS256)
                .compact();
    }

    public Optional<Long> parse(String token, String expectedType) {
        try {
            Claims claims = Jwts.parser().verifyWith(key).build()
                    .parseSignedClaims(token).getPayload();
            if (!expectedType.equals(claims.get("typ"))) {
                return Optional.empty();
            }
            return Optional.of(Long.valueOf(claims.getSubject()));
        } catch (JwtException | IllegalArgumentException e) {
            return Optional.empty();
        }
    }
}

@Service
public class AuthService {

    private final UserRepository users;
    private final PasswordEncoder encoder;
    private final JwtService jwt;

    public AuthService(UserRepository users, PasswordEncoder encoder, JwtService jwt) {
        this.users = users;
        this.encoder = encoder;
        this.jwt = jwt;
    }

    public AuthResponse login(String username, String rawPassword) {
        UserEntity user = users.findByUsername(username)
                .orElseThrow(UnauthorizedException::new);
        if (!encoder.matches(rawPassword, user.getPasswordHash())) {
            throw new UnauthorizedException();
        }
        return issuePair(user);
    }

    public AuthResponse refresh(String refreshToken) {
        Long userId = jwt.parse(refreshToken, "refresh")
                .orElseThrow(UnauthorizedException::new);
        UserEntity user = users.findById(userId)
                .orElseThrow(UnauthorizedException::new);
        return issuePair(user);
    }

    private AuthResponse issuePair(UserEntity user) {
        return new AuthResponse(
                jwt.issue(user.getId(), "access"),
                jwt.issue(user.getId(), "refresh"));
    }
}
